import{_ as t,o as i,c as o,ag as s}from"./chunks/framework.D9ghT4bC.js";const p=JSON.parse('{"title":"UncivCN 文档站建设计划（VitePress 方案）","description":"","frontmatter":{},"headers":[],"relativePath":"DocsSite-Plan.md","filePath":"DocsSite-Plan.md"}'),d={name:"DocsSite-Plan.md"};function a(c,e,r,n,l,u){return i(),o("div",null,[...e[0]||(e[0]=[s(`<h1 id="uncivcn-文档站建设计划-vitepress-方案" tabindex="-1">UncivCN 文档站建设计划（VitePress 方案） <a class="header-anchor" href="#uncivcn-文档站建设计划-vitepress-方案" aria-label="Permalink to &quot;UncivCN 文档站建设计划（VitePress 方案）&quot;">​</a></h1><blockquote><p><strong>状态：阶段 1+2 已实施（2026-08-08），阶段 3 待后续</strong></p><p>已完成：VitePress 工程（docs-vitepress/）+ 英文区（上游 docs 原样）+ i18n 中英切换 + UncivCN 专区 + 社区 41 页移植 + kt 生成器 VitePress 格式/中文输出 + CI 部署（.github/workflows/docs.yml）。 待办（阶段 3）：更新日志自动生成器、搜索优化（pagefind）、Modders 文档逐步翻译。</p><p>目标：在游戏仓库内建 VitePress 文档站，复用上游 md 文档与 Kotlin 文档生成器遗产， 提供中英文切换，并开辟 UncivCN 分支新改动专区。</p><p>本文档是实施蓝图，所有决策与细节均已调研确认，可直接按此执行。</p></blockquote><hr><h2 id="_0-背景与需求" tabindex="-1">0. 背景与需求 <a class="header-anchor" href="#_0-背景与需求" aria-label="Permalink to &quot;0. 背景与需求&quot;">​</a></h2><ul><li>上游 Unciv 有成熟文档遗产：<code>docs/</code> 目录（89 个文件）+ 3 个 Kotlin 文档生成器 （UniqueDocsWriter / UiElementDocsWriter / MergeActionDocsWriter），mkdocs 构建链</li><li>用户另有社区文档仓库 <code>unciv-chinese-community</code>（VitePress 站，47 页中文内容， 含原版攻略、CoeHarMod 专区、开发者专区、更新日志）</li><li>需求： <ol><li>复用上游 md 文档和网页</li><li>添加中文支持，玩家可随意切换中英文</li><li>开辟新页面介绍 UncivCN 分支新改动</li><li>利用 kt 代码自动化生成文档并构建网页</li></ol></li></ul><h2 id="_1-技术路线决策" tabindex="-1">1. 技术路线决策 <a class="header-anchor" href="#_1-技术路线决策" aria-label="Permalink to &quot;1. 技术路线决策&quot;">​</a></h2><table tabindex="0"><thead><tr><th>候选</th><th>结论</th><th>原因</th></tr></thead><tbody><tr><td>mkdocs（上游在用）</td><td>❌ 放弃</td><td><strong>不支持中文搜索</strong>（用户明确要求）</td></tr><tr><td><strong>VitePress</strong>（社区仓库技术路线）</td><td>✅ 采用</td><td>与社区仓库一致；内置 localSearch（minisearch）支持中文；mathjax 公式；<code>: ::</code> 容器与社区文档语法兼容；可 i18n 中英切换</td></tr></tbody></table><h2 id="_2-总体架构" tabindex="-1">2. 总体架构 <a class="header-anchor" href="#_2-总体架构" aria-label="Permalink to &quot;2. 总体架构&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>docs/（上游 89 个 md，英文）            ← 完全复用，作为英文区</span></span>
<span class="line"><span>docs/zh/（中文区，新增）               ← UncivCN 专区 + 移植的社区中文内容</span></span>
<span class="line"><span>desktop DocsWriter（kt 自动生成）      ← 复用 + 扩展中文输出</span></span>
<span class="line"><span>docs-vitepress/（VitePress 工程）      ← config.ts（i18n/搜索/主题）+ package.json</span></span>
<span class="line"><span>.github/workflows/docs.yml            ← CI：kt 生成 → vitepress build → gh-pages</span></span></code></pre></div><h2 id="_3-复用上游遗产-3-件" tabindex="-1">3. 复用上游遗产（3 件） <a class="header-anchor" href="#_3-复用上游遗产-3-件" aria-label="Permalink to &quot;3. 复用上游遗产（3 件）&quot;">​</a></h2><ol><li><strong><code>docs/</code> 89 个 md</strong>：直接作 VitePress 英文区。frontmatter 兼容； mkdocs 特有 <code>!!! note</code> / <code>??? example</code> admonition 需脚本转 <code>::: note</code> 格式 （约 20 处，见 6.2）</li><li><strong>3 个 kt 生成器</strong>：天然继承——CN 分支运行 DesktopLauncher 时会自动重写 <code>docs/Modders/uniques.md</code>、<code>Unique-parameters.md</code> 等，内容自动包含 CN 独有 unique（AllowTileClaim 等）。生成器源码：<code>desktop/src/com/unciv/app/desktop/</code><ul><li>UniqueDocsWriter.kt（uniques.md + Unique-parameters.md，marker 插入）</li><li>UiElementDocsWriter.kt（SkinStrings 等 UI 元素文档）</li><li>MergeActionDocsWriter.kt（MergeAction 文档，CN 分支有历史提交）</li><li>触发点：DesktopLauncher.main 中 <code>if (!isRunFromJAR) { ...DocsWriter().write() }</code></li></ul></li><li><strong>文档网页构建链</strong>：上游 mkdocs workflow 不沿用，仅借鉴结构 （<code>.github/workflows/mkdocs.yml</code>：checkout → 构建 → peaceiris/actions-gh-pages 推 gh-pages 分支）</li></ol><h2 id="_4-中文支持-i18n-语言切换" tabindex="-1">4. 中文支持（i18n 语言切换） <a class="header-anchor" href="#_4-中文支持-i18n-语言切换" aria-label="Permalink to &quot;4. 中文支持（i18n 语言切换）&quot;">​</a></h2><ul><li>VitePress 官方 i18n：<code>/</code> 英文、<code>/zh/</code> 中文，右上角语言切换器</li><li>中文区内容来源（按优先级）： <ol><li><strong>UncivCN 专区</strong>（全新手写）</li><li><strong>移植社区仓库原创内容</strong>：原版攻略 5 页、CoeHarMod 专区 4 页、开发者专区 27 页、 更新日志 5 页（共 41 页；社区 <code>: ::</code> 容器语法与 VitePress 完全兼容，几乎零转换； frontmatter 保留；<code>&lt;Badge&gt;</code> 组件需转纯文本，仅 2 个文件）</li><li><strong>kt 生成器中文输出</strong>：扩展 UniqueDocsWriter 输出中文版 uniques.md—— 利用现有 unique 翻译模板（template.properties 已有全部 unique 中文翻译）</li></ol></li><li>英文区 = 上游 docs/ 原样；中文区逐步扩充，导航只列已存在页面（避免 404）</li></ul><h2 id="_5-uncivcn-新改动专区-核心新页" tabindex="-1">5. UncivCN 新改动专区（核心新页） <a class="header-anchor" href="#_5-uncivcn-新改动专区-核心新页" aria-label="Permalink to &quot;5. UncivCN 新改动专区（核心新页）&quot;">​</a></h2><p><code>docs/zh/UncivCN/</code>：</p><ul><li><code>index.md</code> —— 分支介绍（与上游关系、定位、构建方式）</li><li><code>新特性.md</code> —— 逐项：功能说明 + 启用方式（Lua 模组系统、镜像/环形地图、单位钉、 随机数读档可变性、tile-claim、人口锁地按钮、游戏设置导出/导入剪贴板、 轮询联机、默认服务器、设置隔离等）</li><li><code>更新日志.md</code> —— CN 版本记录（4.21.0.1 → 4.21.5.1 及以后）</li><li><code>与上游差异.md</code> —— 功能对照表</li></ul><p><strong>kt 自动化扩展</strong>：新增 UncivCNDocsWriter（或 CI 步骤），从 git 版本提交历史自动生成 <code>更新日志.md</code> 草稿——复用 <code>docs/CommunitySync-Design.md</code> 3.1 节的版本定位思路 （first-parent 遍历 BuildConfig.kt），用 Kotlin 实现；发版时文档自动更新</p><h2 id="_6-关键技术细节" tabindex="-1">6. 关键技术细节 <a class="header-anchor" href="#_6-关键技术细节" aria-label="Permalink to &quot;6. 关键技术细节&quot;">​</a></h2><h3 id="_6-1-vitepress-工程-docs-vitepress" tabindex="-1">6.1 VitePress 工程（docs-vitepress/） <a class="header-anchor" href="#_6-1-vitepress-工程-docs-vitepress" aria-label="Permalink to &quot;6.1 VitePress 工程（docs-vitepress/）&quot;">​</a></h3><ul><li>复用社区仓库配置经验（<code>.vitepress/config.ts</code>）： <ul><li><code>markdown-it-mathjax3</code>（公式）、<code>markdown-it-task-lists</code>（任务列表）</li><li>主题：可复用社区 custom.css 换色；logo 用 <code>docs/assets/Icon.png</code></li><li>搜索：VitePress 默认 localSearch（中文按字索引，可用）；后续可换 pagefind 增强分词</li></ul></li><li>版本：vitepress ^1.5.0（与社区仓库一致）</li><li>路径规划：vitepress srcDir 指向仓库根 <code>docs/</code>？——注意 mkdocs 的 <code>!!!</code> 语法转换、 i18n 目录结构（<code>docs/zh/</code> 作为中文 locale 目录）需在 config.ts 的 locales 中配置</li></ul><h3 id="_6-2-mkdocs-admonition-转换-脚本-一次性" tabindex="-1">6.2 mkdocs admonition 转换（脚本，一次性） <a class="header-anchor" href="#_6-2-mkdocs-admonition-转换-脚本-一次性" aria-label="Permalink to &quot;6.2 mkdocs admonition 转换（脚本，一次性）&quot;">​</a></h3><ul><li>上游 docs/ 中 <code>!!! note</code> / <code>??? example &quot;...&quot;</code> / <code>??? note &quot;&quot;</code> 等 → <code>::: note</code> / <code>::: example</code> 格式</li><li>已确认上游用法样例： <ul><li><code>!!! note</code>（Making-a-new-Civilization.md 等）</li><li><code>??? example &quot;Gain a free [buildingName] [cityFilter]&quot;</code>（uniques.md 大量，由 kt 生成器输出——<strong>优先改生成器</strong>而非转换产物）</li></ul></li><li>注意：uniques.md / Unique-parameters.md 是 kt 生成器产物，转换逻辑应放进生成器 （或生成器直接输出 VitePress 兼容格式）</li></ul><h3 id="_6-3-kt-文档生成器运行方式" tabindex="-1">6.3 kt 文档生成器运行方式 <a class="header-anchor" href="#_6-3-kt-文档生成器运行方式" aria-label="Permalink to &quot;6.3 kt 文档生成器运行方式&quot;">​</a></h3><ul><li>现状：DocsWriter 在 DesktopLauncher.main 里 <code>isRunFromJAR=false</code> 时执行（启动游戏太重）</li><li>计划：新增轻量 main（如 <code>DocsGenerationMain</code>），只跑三个 DocsWriter + 更新日志生成器， 供 CI 单独调用（<code>./gradlew desktop:run --args=&quot;--generate-docs&quot;</code> 或独立 main class）</li><li>生成器写路径是相对 assets 目录的 <code>../../docs/...</code>，CI 中工作目录需正确设置</li></ul><h3 id="_6-4-构建与部署-github-workflows-docs-yml" tabindex="-1">6.4 构建与部署（.github/workflows/docs.yml） <a class="header-anchor" href="#_6-4-构建与部署-github-workflows-docs-yml" aria-label="Permalink to &quot;6.4 构建与部署（.github/workflows/docs.yml）&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>on: push branches: [UncivCN] + workflow_dispatch</span></span>
<span class="line"><span>1. checkout（fetch-depth 0，供更新日志生成器读 git 历史）</span></span>
<span class="line"><span>2. 跑 kt 文档生成（gradle）</span></span>
<span class="line"><span>3. setup-node + npm ci（docs-vitepress/）</span></span>
<span class="line"><span>4. vitepress build → site/</span></span>
<span class="line"><span>5. peaceiris/actions-gh-pages 推 gh-pages 分支</span></span>
<span class="line"><span>→ 仓库 Settings → Pages：部署源选 gh-pages 分支（用户手动操作一次）</span></span>
<span class="line"><span>→ 网址：autumnpizazz.github.io/Unciv（与上游 yairm210.github.io/Unciv 同构）</span></span></code></pre></div><p>注意：上游 workflow 用 <code>FORCE_JAVASCRIPT_ACTIONS_TO_NODE24: true</code>（Node24 弃用提示），可参考</p><h2 id="_7-与社区仓库的关系" tabindex="-1">7. 与社区仓库的关系 <a class="header-anchor" href="#_7-与社区仓库的关系" aria-label="Permalink to &quot;7. 与社区仓库的关系&quot;">​</a></h2><ul><li>社区仓库原创内容移植进 <code>docs/zh/</code> 后，社区仓库<strong>停更留档</strong>（保留历史，旧链接可访问）</li><li>移植清单：原版专区 5 页、模组专区 4 页、开发者专区 27 页、更新日志 5 页 = 41 页</li><li>社区仓库路径：<code>C:\\Users\\27162\\Documents\\GitHub\\unciv-chinese-community</code>（本地） 云端 <code>github.com/AutumnPizazz/unciv-chinese-community</code></li></ul><h2 id="_8-工作量估算" tabindex="-1">8. 工作量估算 <a class="header-anchor" href="#_8-工作量估算" aria-label="Permalink to &quot;8. 工作量估算&quot;">​</a></h2><table tabindex="0"><thead><tr><th>任务</th><th>工作量</th></tr></thead><tbody><tr><td>VitePress 工程 + i18n + 搜索配置</td><td>0.5 天</td></tr><tr><td>mkdocs admonition 转换（20 处，含生成器侧）</td><td>2 小时</td></tr><tr><td>UncivCN 专区页面（手写中文）</td><td>0.5–1 天</td></tr><tr><td>社区内容移植（41 页，脚本+校对）</td><td>0.5–1 天</td></tr><tr><td>kt 生成器中文输出 + 更新日志生成器</td><td>0.5–1 天</td></tr><tr><td>CI workflow + 部署验证</td><td>2–3 小时</td></tr></tbody></table><h2 id="_9-分阶段实施" tabindex="-1">9. 分阶段实施 <a class="header-anchor" href="#_9-分阶段实施" aria-label="Permalink to &quot;9. 分阶段实施&quot;">​</a></h2><ul><li><strong>阶段 1（最小可用）</strong>：VitePress 工程 + 英文区（上游 docs 原样）+ UncivCN 专区中文页 <ul><li>i18n 切换 + CI 部署 → 上线</li></ul></li><li><strong>阶段 2</strong>：移植社区仓库内容（41 页）、kt 生成器中文输出（uniques 中文版）</li><li><strong>阶段 3</strong>：更新日志自动生成、搜索优化（pagefind 分词）、Modders 文档逐步翻译</li></ul><h2 id="_10-待确认决策-实施前问用户" tabindex="-1">10. 待确认决策（实施前问用户） <a class="header-anchor" href="#_10-待确认决策-实施前问用户" aria-label="Permalink to &quot;10. 待确认决策（实施前问用户）&quot;">​</a></h2><ol><li>部署位置：游戏仓库 Pages（<code>autumnpizazz.github.io/Unciv</code>）——需用户启用 Pages 并选 gh-pages 分支 ✅ 已确认</li><li>阶段 1 先上线还是全部做完再上 ✅ 已确认：阶段 1+2 一次实施</li><li>社区仓库内容全部移植还是先移植开发者专区 ✅ 已确认：脚本全量移植</li><li>kt 生成器扩展范围（中文 uniques 输出、更新日志生成器）是否都做 ✅ 已确认：中文输出做，更新日志生成器留阶段 3</li></ol><h2 id="_10-1-实施记录-2026-08-08" tabindex="-1">10.1 实施记录（2026-08-08） <a class="header-anchor" href="#_10-1-实施记录-2026-08-08" aria-label="Permalink to &quot;10.1 实施记录（2026-08-08）&quot;">​</a></h2><p>已交付：</p><ul><li><code>docs-vitepress/</code>：VitePress 工程（vitepress ^1.5+，base <code>/Unciv/</code>，srcDir=../docs，i18n root/zh） <ul><li>关键坑：locale key 必须用 <code>root</code> + 目录名（<code>/</code> 会被当正则永远匹配，导致 locale 失效）； srcDir 在 docs-vitepress 之外时需 <code>vite.resolve.alias.vue</code> 指回本工程 node_modules</li></ul></li><li>英文区：上游 docs/ 原样复用（admonition 已转 <code>:::</code>，5 处裸 HTML 标签已包反引号）</li><li>中文区 <code>docs/zh/</code>：社区 40 页全量移植（链接加 /zh 前缀、Badge 转文本）+ UncivCN 专区 4 页</li><li>kt 生成器：UniqueDocsWriter 输出 VitePress 容器格式 + 中文版 Unique能力列表.md（复用 Simplified_Chinese.properties 翻译 + 内置文档句翻译）；MergeActionDocsWriter 同步转换； DesktopLauncher 与新增轻量入口 <code>DocsGenerationMain</code>（<code>./gradlew desktop:generateDocs</code>）</li><li>CI：<code>.github/workflows/docs.yml</code>（push UncivCN/master + workflow_dispatch → gradle 生成 → npm ci/build → 链接检查 → gh-pages）</li><li>工具脚本：<code>docs-vitepress/scripts/</code>（转换/移植/链接检查）</li></ul><p>遗留：</p><ul><li>用户需在仓库 Settings → Pages 选择 gh-pages 分支部署源（一次手动操作）</li><li>英文独有页面（Credits、Developers/* 等）在中文区的语言切换会 404（VitePress 固有行为， 翻译完成后自然消失）</li><li>社区版 Unique能力列表.md 的 tooltip（span title）结构未保留，由生成器版替代（信息等量， 无悬浮提示）</li><li>阶段 3：更新日志自动生成、pagefind、Modders 文档逐步翻译</li></ul><h2 id="_10-3-自动生成-vs-人工维护清单-2026-08-09" tabindex="-1">10.3 自动生成 vs 人工维护清单（2026-08-09） <a class="header-anchor" href="#_10-3-自动生成-vs-人工维护清单-2026-08-09" aria-label="Permalink to &quot;10.3 自动生成 vs 人工维护清单（2026-08-09）&quot;">​</a></h2><p>经源码审计，文档站文件分两类，维护方式必须区分：</p><table tabindex="0"><thead><tr><th>文件</th><th>生成器</th><th>维护方式</th></tr></thead><tbody><tr><td>docs/Modders/uniques.md</td><td>UniqueDocsWriter.write()</td><td><strong>整体自动</strong>，改生成器源码</td></tr><tr><td>docs/zh/Modders/uniques.md</td><td>UniqueDocsWriter.writeChinese()</td><td><strong>整体自动</strong>，改生成器源码</td></tr><tr><td>docs/Modders/Unique-parameters.md</td><td>UniqueDocsWriter.writeCountables()</td><td>marker 区间自动，其余人工</td></tr><tr><td>docs/zh/Modders/Unique-parameters.md</td><td>UniqueDocsWriter.writeCountables()（新增）</td><td>marker 区间自动（中文翻译内置在生成器），其余人工</td></tr><tr><td>docs/Modders/Mod-file-structure/6-MergeActions.md</td><td>MergeActionDocsWriter</td><td><strong>整体自动</strong></td></tr><tr><td>docs/Modders/Creating-a-UI-skin.md</td><td>UiElementDocsWriter</td><td>marker 区间自动，其余人工</td></tr><tr><td>docs/zh/Modders/Creating-a-UI-skin.md</td><td>UiElementDocsWriter（新增中文输出）</td><td>marker 区间自动，其余人工</td></tr><tr><td>其余 docs/、docs/zh/ 页面</td><td>—</td><td>人工维护</td></tr></tbody></table><p>原则：自动生成的文档<strong>只通过改生成器源码 + 重新运行生成器维护</strong>（ <code>./gradlew desktop:generateDocs</code>），不得人工编辑产物；人工文档（含社区翻译） 直接维护。生成器内置的文档中文翻译（docsSentence / countablesTranslate） 同样随源码维护。</p><h2 id="_10-2-中文区重构与全量翻译-2026-08-09" tabindex="-1">10.2 中文区重构与全量翻译（2026-08-09） <a class="header-anchor" href="#_10-2-中文区重构与全量翻译-2026-08-09" aria-label="Permalink to &quot;10.2 中文区重构与全量翻译（2026-08-09）&quot;">​</a></h2><p>按用户要求，中文区抛弃社区仓库的目录结构，改为<strong>英文文档的翻译镜像</strong>：</p><ul><li>新结构：<code>docs/zh/{Modders, Developers, Translating, Other}/</code> 与英文一一对应（同名文件）， 语言切换同一路径即对应翻译；社区独有内容保留在 <code>UncivCN/</code>、<code>原版专区/</code>、<code>模组专区/</code>、<code>更新日志/</code></li><li>19 个已有社区翻译迁入镜像位置（restructure_zh.py + fix_zh_links.py + fix_zh_anchors.py）， 内部链接全部重写为 /zh/ 绝对路径，顺带修复社区原有死链</li><li><strong>全量补齐翻译</strong>（16 个缺失文档）：Developers 6 个 + Other 6 个 + 顶层 4 个（Credits 由 translate_credits.py 生成：翻译标题/说明，保留名单）——中英 36 个文档现在一一对应</li><li>生成器：中文 uniques 输出路径改为 <code>docs/zh/Modders/uniques.md</code>；mkdocs 缩写语法 <code>*[param]: desc</code> 改为标准参数表（VitePress 不识别缩写）</li><li>config.ts 中文导航重写为镜像结构；构建验证 0 死链、0 渲染残留（DocsSite-Plan 除外）</li></ul><h2 id="_11-相关参考" tabindex="-1">11. 相关参考 <a class="header-anchor" href="#_11-相关参考" aria-label="Permalink to &quot;11. 相关参考&quot;">​</a></h2><ul><li>联动设计文档（含版本定位算法、跨仓库教训）：<code>docs/CommunitySync-Design.md</code></li><li>上游 mkdocs workflow：<code>.github/workflows/mkdocs.yml</code>（已删除？见 git 历史）</li><li>上游 mkdocs 配置：<code>mkdocs.yml</code>（若已随上游合入仍在仓库根）</li><li>kt 生成器源码：<code>desktop/src/com/unciv/app/desktop/UniqueDocsWriter.kt</code> 等</li><li>社区仓库 VitePress 配置：<code>unciv-chinese-community/.vitepress/config.ts</code></li></ul>`,49)])])}const m=t(d,[["render",a]]);export{p as __pageData,m as default};
